macro_rules! Advice {
    () => {
        # [doc = " Values supported by [`Mmap::advise`][crate::Mmap::advise] and [`MmapMut::advise`][crate::MmapMut::advise] functions."] # [doc = ""] # [doc = " See [madvise()](https://man7.org/linux/man-pages/man2/madvise.2.html) map page."] # [repr (i32)] # [derive (Clone , Copy , Debug , Eq , PartialEq , Hash)] pub enum Advice { # [doc = " **MADV_NORMAL**"] # [doc = ""] # [doc = " No special treatment.  This is the default."] Normal = libc :: MADV_NORMAL , # [doc = " **MADV_RANDOM**"] # [doc = ""] # [doc = " Expect page references in random order.  (Hence, read"] # [doc = " ahead may be less useful than normally.)"] Random = libc :: MADV_RANDOM , # [doc = " **MADV_SEQUENTIAL**"] # [doc = ""] # [doc = " Expect page references in sequential order.  (Hence, pages"] # [doc = " in the given range can be aggressively read ahead, and may"] # [doc = " be freed soon after they are accessed.)"] Sequential = libc :: MADV_SEQUENTIAL , # [doc = " **MADV_WILLNEED**"] # [doc = ""] # [doc = " Expect access in the near future.  (Hence, it might be a"] # [doc = " good idea to read some pages ahead.)"] WillNeed = libc :: MADV_WILLNEED , # [doc = " **MADV_DONTFORK** - Linux only (since Linux 2.6.16)"] # [doc = ""] # [doc = " Do not make the pages in this range available to the child"] # [doc = " after a fork(2).  This is useful to prevent copy-on-write"] # [doc = " semantics from changing the physical location of a page if"] # [doc = " the parent writes to it after a fork(2).  (Such page"] # [doc = " relocations cause problems for hardware that DMAs into the"] # [doc = " page.)"] # [cfg (target_os = "linux")] DontFork = libc :: MADV_DONTFORK , # [doc = " **MADV_DOFORK** - Linux only (since Linux 2.6.16)"] # [doc = ""] # [doc = " Undo the effect of MADV_DONTFORK, restoring the default"] # [doc = " behavior, whereby a mapping is inherited across fork(2)."] # [cfg (target_os = "linux")] DoFork = libc :: MADV_DOFORK , # [doc = " **MADV_MERGEABLE** - Linux only (since Linux 2.6.32)"] # [doc = ""] # [doc = " Enable Kernel Samepage Merging (KSM) for the pages in the"] # [doc = " range specified by addr and length.  The kernel regularly"] # [doc = " scans those areas of user memory that have been marked as"] # [doc = " mergeable, looking for pages with identical content."] # [doc = " These are replaced by a single write-protected page (which"] # [doc = " is automatically copied if a process later wants to update"] # [doc = " the content of the page).  KSM merges only private"] # [doc = " anonymous pages (see mmap(2))."] # [doc = ""] # [doc = " The KSM feature is intended for applications that generate"] # [doc = " many instances of the same data (e.g., virtualization"] # [doc = " systems such as KVM).  It can consume a lot of processing"] # [doc = " power; use with care.  See the Linux kernel source file"] # [doc = " Documentation/admin-guide/mm/ksm.rst for more details."] # [doc = ""] # [doc = " The MADV_MERGEABLE and MADV_UNMERGEABLE operations are"] # [doc = " available only if the kernel was configured with"] # [doc = " CONFIG_KSM."] # [cfg (target_os = "linux")] Mergeable = libc :: MADV_MERGEABLE , # [doc = " **MADV_UNMERGEABLE** - Linux only (since Linux 2.6.32)"] # [doc = ""] # [doc = " Undo the effect of an earlier MADV_MERGEABLE operation on"] # [doc = " the specified address range; KSM unmerges whatever pages"] # [doc = " it had merged in the address range specified by addr and"] # [doc = " length."] # [cfg (target_os = "linux")] Unmergeable = libc :: MADV_UNMERGEABLE , # [doc = " **MADV_HUGEPAGE** - Linux only (since Linux 2.6.38)"] # [doc = ""] # [doc = " Enable Transparent Huge Pages (THP) for pages in the range"] # [doc = " specified by addr and length.  Currently, Transparent Huge"] # [doc = " Pages work only with private anonymous pages (see"] # [doc = " mmap(2)).  The kernel will regularly scan the areas marked"] # [doc = " as huge page candidates to replace them with huge pages."] # [doc = " The kernel will also allocate huge pages directly when the"] # [doc = " region is naturally aligned to the huge page size (see"] # [doc = " posix_memalign(2))."] # [doc = ""] # [doc = " This feature is primarily aimed at applications that use"] # [doc = " large mappings of data and access large regions of that"] # [doc = " memory at a time (e.g., virtualization systems such as"] # [doc = " QEMU).  It can very easily waste memory (e.g., a 2 MB"] # [doc = " mapping that only ever accesses 1 byte will result in 2 MB"] # [doc = " of wired memory instead of one 4 KB page).  See the Linux"] # [doc = " kernel source file"] # [doc = " Documentation/admin-guide/mm/transhuge.rst for more"] # [doc = " details."] # [doc = ""] # [doc = " Most common kernels configurations provide MADV_HUGEPAGE-"] # [doc = " style behavior by default, and thus MADV_HUGEPAGE is"] # [doc = " normally not necessary.  It is mostly intended for"] # [doc = " embedded systems, where MADV_HUGEPAGE-style behavior may"] # [doc = " not be enabled by default in the kernel.  On such systems,"] # [doc = " this flag can be used in order to selectively enable THP."] # [doc = " Whenever MADV_HUGEPAGE is used, it should always be in"] # [doc = " regions of memory with an access pattern that the"] # [doc = " developer knows in advance won't risk to increase the"] # [doc = " memory footprint of the application when transparent"] # [doc = " hugepages are enabled."] # [doc = ""] # [doc = " The MADV_HUGEPAGE and MADV_NOHUGEPAGE operations are"] # [doc = " available only if the kernel was configured with"] # [doc = " CONFIG_TRANSPARENT_HUGEPAGE."] # [cfg (target_os = "linux")] HugePage = libc :: MADV_HUGEPAGE , # [doc = " **MADV_NOHUGEPAGE** - Linux only (since Linux 2.6.38)"] # [doc = ""] # [doc = " Ensures that memory in the address range specified by addr"] # [doc = " and length will not be backed by transparent hugepages."] # [cfg (target_os = "linux")] NoHugePage = libc :: MADV_NOHUGEPAGE , # [doc = " **MADV_DONTDUMP** - Linux only (since Linux 3.4)"] # [doc = ""] # [doc = " Exclude from a core dump those pages in the range"] # [doc = " specified by addr and length.  This is useful in"] # [doc = " applications that have large areas of memory that are"] # [doc = " known not to be useful in a core dump.  The effect of"] # [doc = " **MADV_DONTDUMP** takes precedence over the bit mask that is"] # [doc = " set via the `/proc/[pid]/coredump_filter` file (see"] # [doc = " core(5))."] # [cfg (target_os = "linux")] DontDump = libc :: MADV_DONTDUMP , # [doc = " **MADV_DODUMP** - Linux only (since Linux 3.4)"] # [doc = ""] # [doc = " Undo the effect of an earlier MADV_DONTDUMP."] # [cfg (target_os = "linux")] DoDump = libc :: MADV_DODUMP , # [doc = " **MADV_HWPOISON** - Linux only (since Linux 2.6.32)"] # [doc = ""] # [doc = " Poison the pages in the range specified by addr and length"] # [doc = " and handle subsequent references to those pages like a"] # [doc = " hardware memory corruption.  This operation is available"] # [doc = " only for privileged (CAP_SYS_ADMIN) processes.  This"] # [doc = " operation may result in the calling process receiving a"] # [doc = " SIGBUS and the page being unmapped."] # [doc = ""] # [doc = " This feature is intended for testing of memory error-"] # [doc = " handling code; it is available only if the kernel was"] # [doc = " configured with CONFIG_MEMORY_FAILURE."] # [cfg (target_os = "linux")] HwPoison = libc :: MADV_HWPOISON , # [doc = " **MADV_POPULATE_READ** - Linux only (since Linux 5.14)"] # [doc = ""] # [doc = " Populate  (prefault)  page  tables readable, faulting in all"] # [doc = " pages in the range just as  if  manually  reading  from  each"] # [doc = " page; however, avoid the actual memory access that would have"] # [doc = " been performed after handling the fault."] # [doc = ""] # [doc = " In contrast to MAP_POPULATE, MADV_POPULATE_READ does not hide"] # [doc = " errors,  can  be  applied to (parts of) existing mappings and"] # [doc = " will always populate (prefault) page  tables  readable.   One"] # [doc = " example  use  case is prefaulting a file mapping, reading all"] # [doc = " file content from disk; however, pages won't be  dirtied  and"] # [doc = " consequently  won't  have  to  be  written  back to disk when"] # [doc = " evicting the pages from memory."] # [doc = ""] # [doc = " Depending on the underlying mapping, map the shared zeropage,"] # [doc = " preallocate  memory  or  read the underlying file; files with"] # [doc = " holes might or might not preallocate blocks.   If  populating"] # [doc = " fails, a SIGBUS signal is not generated; instead, an error is"] # [doc = " returned."] # [doc = ""] # [doc = " If MADV_POPULATE_READ succeeds, all  page  tables  have  been"] # [doc = " populated  (prefaulted) readable once.  If MADV_POPULATE_READ"] # [doc = " fails, some page tables might have been populated."] # [doc = ""] # [doc = " MADV_POPULATE_READ cannot be applied to mappings without read"] # [doc = " permissions  and  special  mappings,  for  example,  mappings"] # [doc = " marked with kernel-internal flags such as VM_PFNMAP or VM_IO,"] # [doc = " or secret memory regions created using memfd_secret(2)."] # [doc = ""] # [doc = " Note  that with MADV_POPULATE_READ, the process can be killed"] # [doc = " at any moment when the system runs out of memory."] # [cfg (target_os = "linux")] PopulateRead = libc :: MADV_POPULATE_READ , # [doc = " **MADV_POPULATE_WRITE** - Linux only (since Linux 5.14)"] # [doc = ""] # [doc = " Populate (prefault) page tables  writable,  faulting  in  all"] # [doc = " pages  in  the range just as if manually writing to each each"] # [doc = " page; however, avoid the actual memory access that would have"] # [doc = " been performed after handling the fault."] # [doc = ""] # [doc = " In  contrast  to  MAP_POPULATE,  MADV_POPULATE_WRITE does not"] # [doc = " hide errors, can be applied to (parts of)  existing  mappings"] # [doc = " and  will  always  populate  (prefault) page tables writable."] # [doc = " One example use case is preallocating  memory,  breaking  any"] # [doc = " CoW (Copy on Write)."] # [doc = ""] # [doc = " Depending  on  the  underlying mapping, preallocate memory or"] # [doc = " read the underlying file; files with holes  will  preallocate"] # [doc = " blocks.   If  populating fails, a SIGBUS signal is not gener‐"] # [doc = " ated; instead, an error is returned."] # [doc = ""] # [doc = " If MADV_POPULATE_WRITE succeeds, all page  tables  have  been"] # [doc = " populated (prefaulted) writable once.  If MADV_POPULATE_WRITE"] # [doc = " fails, some page tables might have been populated."] # [doc = ""] # [doc = " MADV_POPULATE_WRITE cannot be  applied  to  mappings  without"] # [doc = " write permissions and special mappings, for example, mappings"] # [doc = " marked with kernel-internal flags such as VM_PFNMAP or VM_IO,"] # [doc = " or secret memory regions created using memfd_secret(2)."] # [doc = ""] # [doc = " Note that with MADV_POPULATE_WRITE, the process can be killed"] # [doc = " at any moment when the system runs out of memory."] # [cfg (target_os = "linux")] PopulateWrite = libc :: MADV_POPULATE_WRITE , # [doc = " **MADV_ZERO_WIRED_PAGES** - Darwin only"] # [doc = ""] # [doc = " Indicates that the application would like the wired pages in this address range to be"] # [doc = " zeroed out if the address range is deallocated without first unwiring the pages (i.e."] # [doc = " a munmap(2) without a preceding munlock(2) or the application quits).  This is used"] # [doc = " with `madvise()` system call."] # [cfg (target_vendor = "apple")] ZeroWiredPages = libc :: MADV_ZERO_WIRED_PAGES , }
    };
}

Advice!()